      de: ["Kopenhagen", "Stadtteil", "Wohnen", "Natur"],
      hu: ["Koppenhága", "Városrész", "Lakóhely", "Természet"],
      ro: ["Copenhaga", "Cartier", "Rezidențial", "Natură"],
      en: ["Copenhagen", "District", "Residential", "Nature"],
